	public static AnimationDefinition of(PlutusAnim anim) {
		return switch (anim) {
			case IDLE -> IDLE;
			case WALK -> WALK;
			case FIST -> FIST;
			case GOLD -> GOLD;
			case LUNGE -> LUNGE;
			case PAPE -> PAPE;
			case STAGGER -> STAGGER;
			case PHASE -> PHASE;
			case INTRO -> INTRO;
			case HURT -> HURT;
			case DEATH -> DEATH;
		};
	}

	/** Every animation, in PlutusAnim's order. */
	public static List<AnimationDefinition> all() {
		return Arrays.stream(PlutusAnim.values()).map(PlutusAnimations::of).toList();
	}
